/// Manifest row: `pin pin_a_worded_command_is_refused` in shir_native_command_noop_cond_sync.txt.
/// `! command -v ls >''` keeps the shell-out: the answer depends on the WORD (and on whether ls resolves), so no constant may be written — measured below
#[test]
fn pin_a_worded_command_is_refused() {
    let mut stmt = cnn_stmt(cnn_cond(true, cnn_inner(&["command", "-v", "ls"]), vec![cnn_spec(1, "")]));
    assert!(!native_command_noop_cond(&mut stmt),
        "a worded `command` must keep the shell-out");
    assert!(cnn_written(&stmt).is_none());
    // the refusal is right: the answer depends on the WORD
    assert_eq!(cnn_bash("! command -v ls"), 1, "ls resolves");
    assert_eq!(cnn_bash("! command -v no-such-cmd-sh2perl"), 0,
        "an unknown name flips the condition, so no constant is decided");
}

